beforeExample:
package test;

import org.eclipse.jface.text.source.ICharacterPairMatcher;

public class TestClass {
    public void calculateOffset(int anchor, int offset, int length) {
        int targetOffset = (ICharacterPairMatcher.RIGHT == anchor) ? offset + 1 : offset + length;
        System.out.println(targetOffset);
    }
    public void calculateOtherOffset(int anchor, int offset, int length) {
        int otherOffset = (ICharacterPairMatcher.LEFT == anchor) ? offset : offset + length;
        System.out.println(otherOffset);
    }
}

afterExample:
package test;

import org.eclipse.jface.text.source.ICharacterPairMatcher;

public class TestClass {
    public void calculateOffset(int anchor, int offset, int length) {
        int targetOffset = (ICharacterPairMatcher.RIGHT == anchor) ? offset + 1 : offset + length - 1;
        System.out.println(targetOffset);
    }
    public void calculateOtherOffset(int anchor, int offset, int length) {
        int otherOffset = (ICharacterPairMatcher.LEFT == anchor) ? offset : offset + length;
        System.out.println(otherOffset);
    }
}

